import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Create plane geometry maintaining 512:320 aspect ratio (1.6:1)
  const width = 2.5;
  const height = width / 1.6;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load brushed metal texture
  const metalTexture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  metalTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL texture node
  const colorNode = texture(metalTexture);
  const material = new MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Set scene placement properties
  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalTexture.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
